from pathlib import Path
import json,subprocess,hashlib,datetime,re
root=Path('/opt/phone-cloud-platform');run=lambda a:subprocess.check_output(a,text=True,timeout=40).strip()
c=json.loads(run(['docker','inspect','phone-cloud-platform']))[0];active=json.loads((root/'ACTIVE_PLATFORM_RELEASE.json').read_text())
assert active['version']=='platform-api-entry-20261012-deployed.1', 'Production version changed; reconcile new release before continuing'
assert c['State']['Health']['Status']=='healthy' and c['RestartCount']==0 and not c['State']['OOMKilled'], 'Business runtime unhealthy or restarted'
rows=json.loads((root/'staging/platform-api-entry-20261012-rc.1/EXPECTED_HASHES.json').read_text())
code="const fs=require('fs'),h=require('crypto'),rows=JSON.parse(process.argv[1]);const bad=rows.filter(r=>h.createHash('sha256').update(fs.readFileSync('/app/'+r.path)).digest('hex')!==r.sha256);console.log(JSON.stringify({checked:rows.length,passed:!bad.length,differences:bad.map(r=>r.path)}));if(bad.length)process.exit(1)"
hashes=json.loads(run(['docker','exec','phone-cloud-platform','node','-e',code,json.dumps(rows)]))
compose=[]
for row in active['activeCompose']:
    got=hashlib.sha256(Path(row['path']).read_bytes()).hexdigest();compose.append({'path':row['path'],'passed':got==row['sha256'],'sha256':got})
pid=str(c['State']['Pid']);media=json.loads(run(['/proc/'+pid+'/root/lib/ld-musl-x86_64.so.1','--library-path','/proc/'+pid+'/root/usr/lib:/proc/'+pid+'/root/lib','/proc/'+pid+'/root/usr/local/bin/node','/opt/phone-cloud-platform/deploy/mediamtx-pacing/verify.mjs','--live']))
js=r'''const {Client}=require('pg');const fs=require('fs');(async()=>{const base='http://127.0.0.1:8787',h={Authorization:'Bearer '+process.env.ADMIN_API_TOKEN};const r={http:[]};for(const p of ['/healthz','/readyz','/','/styles.css?v=20261012-api-entry-v1','/app.js','/api-docs.html','/api-docs.css','/api-docs.js','/api-reference.json','/openapi.json']){const resp=await fetch(base+p),text=await resp.text();r.http.push({path:p,status:resp.status,bytes:Buffer.byteLength(text)});if(resp.status!==200)throw Error('HTTP resource failed');if(p==='/readyz'){const j=JSON.parse(text);r.ready={storageOk:j.storage?.ok,storageBackend:j.storage?.backend,runtimeOk:j.runtime?.ok,runtimeMode:j.runtime?.mode}}}r.auth=[];for(const path of ['/api/v1/devices','/api/v1/user/devices','/api/v1/windows-agents']){const no=await fetch(base+path),yes=await fetch(base+path,{headers:h});r.auth.push({path,noAuth:no.status,authorized:yes.status});if(no.status!==401||yes.status!==200)throw Error('Auth guard failed');const j=await yes.json();if(path==='/api/v1/devices')r.adminInventory={total:j.devices.length,online:j.devices.filter(d=>d.adb?.state==='device').length,occupied:j.devices.filter(d=>d.occupancy).length};if(path==='/api/v1/user/devices')r.publicInventory={listed:j.devices.length,online:j.devices.filter(d=>d.online).length,available:j.devices.filter(d=>d.available).length};if(path==='/api/v1/windows-agents')r.agents=j.agents.map(a=>({id:a.agentId,lastSeenAt:a.lastSeenAt,healthCheckedAt:a.health?.checkedAt,status:a.health?.status,screenConnected:a.health?.screenControl?.connected,scanAt:a.health?.lastScan?.finishedAt||a.health?.lastScan?.at||null}));}const db=new Client({connectionString:process.env.DATABASE_URL});await db.connect();await db.query('begin read only');r.databaseCounts={};for(const t of ['phone_cloud_devices','phone_cloud_automation_sessions','phone_cloud_windows_tasks'])r.databaseCounts[t]=(await db.query('select count(*)::int as n from '+t)).rows[0].n;await db.query('rollback');await db.end();r.notification={configured:!!process.env.LOOKUP_HUMAN_FEISHU_WEBHOOK_FILE,secretReadable:!!process.env.LOOKUP_HUMAN_FEISHU_WEBHOOK_FILE&&fs.existsSync(process.env.LOOKUP_HUMAN_FEISHU_WEBHOOK_FILE),persistentReceiptDirectory:fs.existsSync('/app/data/lookup-human-notifications')};console.log(JSON.stringify(r));})().catch(()=>{console.error('Read-only production assertion failed');process.exit(1)})'''
read=json.loads(run(['docker','exec','phone-cloud-platform','node','-e',js]))
log=subprocess.run(['docker','logs','--since','2026-10-11T16:41:00Z','--tail','3000','phone-cloud-platform'],capture_output=True,text=True,timeout=20);txt=log.stdout+log.stderr
markers={p:len(re.findall(re.escape(p),txt,re.I)) for p in ['uncaughtException','unhandledRejection','MODULE_NOT_FOUND','saveState failed','persistence failed','lookup human notification receipt unavailable','out of memory']}
stats=json.loads(run(['docker','stats','--no-stream','--format','{{json .}}','phone-cloud-platform']))
r={'atUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'activeVersion':active['version'],'activeRecordSha256':hashlib.sha256((root/'ACTIVE_PLATFORM_RELEASE.json').read_bytes()).hexdigest(),'container':{'id':c['Id'],'pid':c['State']['Pid'],'baseImage':c['Image'],'health':c['State']['Health']['Status'],'restartCount':c['RestartCount'],'oomKilled':c['State']['OOMKilled'],'startedAt':c['State']['StartedAt']},'restartImageId':active['restartImageId'],'runtimeHashes':hashes,'compose':compose,'mediaLive':media,'readOnlyChecks':read,'logs':{'since':'2026-10-11T16:41:00Z','tailLimit':3000,'linesSampled':len(txt.splitlines()),'fatalMarkers':markers,'rawLogsPublished':False},'resources':{'cpu':stats['CPUPerc'],'memory':stats['MemUsage'],'pids':stats['PIDs']},'productionWrites':0,'realQueries':0,'feishuAttempts':0}
assert all(p['passed'] for p in compose)
now=datetime.datetime.now(datetime.timezone.utc)
agent=next(a for a in read['agents'] if a['id']=='win-bf-202605262318-20260727')
age=(now-datetime.datetime.fromisoformat(agent['lastSeenAt'].replace('Z','+00:00'))).total_seconds()
assert 0 <= age <= 120 and agent['status']=='ok' and agent['screenConnected'], 'Production Agent heartbeat/health stale'
r['productionAgentHeartbeatAgeSeconds']=round(age,2)
assert not any(markers.values()), 'Fatal marker in bounded production log sample'
print(json.dumps(r))
